import os, glob, re

def load_grids():
    d = os.path.normpath(os.environ.get('RLM_SESSION_DIR', ''))
    if not d:
        return {}
    session_file = d + '/../../sessions/' + os.path.basename(d) + '.jsonl'
    try:
        with open(session_file, 'r') as f:
            text = f.read()
    except:
        return {}

    G = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', text):
        k, h, w = m[1], int(m[2]), int(m[3])
        rows = [r.split() for r in text[m.end():].split('\n')[:h]]
        if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
            G[k] = [[int(x) for x in r] for r in rows]
    return G

G = load_grids()
print("Current grids:", sorted(G.keys()))
for k in sorted(G):
    print(f"\n{k}: {G[k]}")

